CREATE TABLE "attendance_regularizations" ("id" TEXT NOT NULL, "companyId" TEXT NOT NULL, "employeeId" TEXT NOT NULL, "workDate" DATE NOT NULL, "checkIn" TIMESTAMP(3) NOT NULL, "checkOut" TIMESTAMP(3) NOT NULL, "reason" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'Pending', "attendanceId" TEXT, "reviewNote" TEXT, "reviewedBy" TEXT, "reviewedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "attendance_regularizations_pkey" PRIMARY KEY ("id"));
CREATE INDEX "attendance_regularizations_companyId_status_createdAt_idx" ON "attendance_regularizations"("companyId","status","createdAt");
CREATE INDEX "attendance_regularizations_companyId_employeeId_workDate_idx" ON "attendance_regularizations"("companyId","employeeId","workDate");
ALTER TABLE "attendance_regularizations" ADD CONSTRAINT "attendance_regularizations_companyId_fkey" FOREIGN KEY ("companyId") REFERENCES "companies"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "attendance_regularizations" ADD CONSTRAINT "attendance_regularizations_employeeId_companyId_fkey" FOREIGN KEY ("employeeId","companyId") REFERENCES "employees"("id","companyId") ON DELETE CASCADE ON UPDATE CASCADE;
